import sys
from math import gcd

def solve():
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    K = int(data[1])
    X = list(map(int, data[2:2+K]))
    Q = int(data[2+K])
    queries = [(int(data[2+K+2*i]), int(data[2+K+2*i+1])) for i in range(Q)]

    def lcm(a, b):
        return abs(a*b) // gcd(a, b)

    LCM = 1
    for jump in X:
        LCM = lcm(LCM, jump)

    # Each cycle of the array has the following effect on each element
    cycle_counts = [0] * LCM
    for jump in X:
        for i in range(jump):
            if (i % jump) == 0:
                cycle_counts[i] += 1

    # Calculate the effect of each cycle
    full_cycles = N // LCM
    remainder_cycles = N % LCM

    cycle_sum = [count * full_cycles for count in cycle_counts]
    for i in range(remainder_cycles):
        cycle_sum[i] += cycle_counts[i]

    # Answer queries
    results = []
    for L, R in queries:
        result = sum(cycle_sum[i] for i in range(L, R+1))
        results.append(result)

    for result in results:
        print(result)

if __name__ == "__main__":
    solve()

